/**
 * Supervises the Agent Host utilityProcess.
 * Forwards MessagePorts between renderer and Host; restarts on crash.
 */
import { app, utilityProcess, MessageChannelMain, type UtilityProcess, type MessagePortMain } from "electron";
import fs from "fs";
import path from "path";
import { appendMainLog, appendMainLogs } from "./logger";
import type { ToolchainSnapshot } from "../shared/toolchains/types";
import type { BrowserCapabilitySnapshot } from "../contract/browser";
import { BrowserError } from "./browser/browser-error";
import { createHostExitSignal, reserveHostRestart, trySpawnHost, type HostExitSignal } from "./host-restart-core";
import { HostOutputLineBuffer } from "./logger-core";
import { randomUUID } from "node:crypto";
import { evaluateHeartbeatTick } from "../shared/heartbeat-liveness";

const CRASH_WINDOW_MS = 30_000;
const MAX_RESTARTS = 2;
const PING_INTERVAL_MS = 15_000;
const PING_TIMEOUT_MS = 10_000;

export type HostStatus = "starting" | "ready" | "crashed" | "stopped";

export type HostMessage =
  | { type: "ready"; ts?: number; piVersion?: string }
  | { type: "pong"; ts?: number }
  | { type: "log"; message: string }
  | { type: "running-sessions"; sessionIds: string[] }
  | { type: "agent-end"; sessionId: string; eventType?: string }
  | { type: "toolchain:ack"; revision: number }
  | { type: "browser:ack"; revision: number }
  | { type: "managed-process-owner:ack"; version: 1; hostInstanceId: string }
  | { type: string; [key: string]: unknown };

export class HostManager {
  private child: UtilityProcess | null = null;
  private childExitSignal: HostExitSignal | null = null;
  private status: HostStatus = "stopped";
  private restartTimes: number[] = [];
  private pingTimer: ReturnType<typeof setInterval> | null = null;
  private lastPong = 0;
  private lastPingTick = 0;
  private onStatusChange: ((s: HostStatus, detail?: string) => void) | null = null;
  private onHostMessage: ((msg: HostMessage) => void) | null = null;
  private pendingPorts: MessagePortMain[] = [];
  private wasReadyBeforeExit = false;
  private requestHandler: ((method: string, params: unknown) => Promise<unknown>) | null = null;
  private beforeRestartHandler: (() => Promise<void>) | null = null;
  private toolchainSnapshot: ToolchainSnapshot | null = null;
  private toolchainAckRevision = -1;
  private browserCapabilitySnapshot: BrowserCapabilitySnapshot | null = null;
  private browserAckRevision = -1;
  private piVersion: string | null = null;
  private hostInstanceId: string | null = null;
  private managedProcessOwnerReady = false;

  constructor(private readonly hostEntry: string) {}

  setStatusListener(cb: (s: HostStatus, detail?: string) => void): void {
    this.onStatusChange = cb;
  }

  setMessageListener(cb: (msg: HostMessage) => void): void {
    this.onHostMessage = cb;
  }

  setRequestHandler(cb: (method: string, params: unknown) => Promise<unknown>): void {
    this.requestHandler = cb;
  }

  setBeforeRestartHandler(cb: () => Promise<void>): void {
    this.beforeRestartHandler = cb;
  }

  getStatus(): HostStatus {
    return this.status;
  }

  getPiVersion(): string | null {
    return this.piVersion;
  }

  getManagedProcessOwnerState(): { hostInstanceId: string | null; ready: boolean } {
    return { hostInstanceId: this.hostInstanceId, ready: this.managedProcessOwnerReady };
  }

  setToolchainSnapshot(snapshot: ToolchainSnapshot): void {
    this.toolchainSnapshot = structuredClone(snapshot);
    if (this.child && this.status === "ready") {
      this.postToolchainSnapshot("toolchain:changed");
    }
  }

  getToolchainAckRevision(): number {
    return this.toolchainAckRevision;
  }

  setBrowserCapabilitySnapshot(snapshot: BrowserCapabilitySnapshot): void {
    this.browserCapabilitySnapshot = structuredClone(snapshot);
    if (this.child && this.status === "ready") this.postBrowserSnapshot("browser:changed");

import type {
  AgentCommand,
  AgentEvent,
  CredentialMutationResult,
  DirEntry,
  EntryContentResult,
  FileContent,
  FileMeta,
  HistoryWindow,
  LoginProgressEvent,
  ModelPreferencesResult,
  ModelsConfig,
  ModelsConfigSnapshot,
  ModelsListResult,
  PagedContextInfo,
  ProviderStatus,
  RunningStateEvent,
  SessionDetail,
  SessionInfo,
  TestResult,
  WorktreeInfo,
} from "./types";
import type {
  GitStatusResult,
  PluginActionParams,
  PluginsResponse,
  SkillRecord,
  SkillUpdateParams,
} from "../shared/api-types";
import type {
  ChannelAccountConfig,
  ChannelBinding,
  ChannelBindingChange,
  ChannelLoginEvent,
  ChannelLoginStartRequest,
  ChannelProbeResult,
  ChannelsSnapshot,
  ChannelStatus,
  ChannelPairingRequest,
  ChannelActivity,
  ChannelId,
  ChannelTestSendResult,
} from "../shared/channel-types";
import type { ToolCapabilityId, ToolProvider } from "../shared/toolchains/types";
import type {
  ManagedProcessChangedEvent,
  ManagedProcessLogStream,
  ManagedProcessLogWindow,
  ManagedProcessOutputEvent,
  ManagedProcessPublicInfo,
  ManagedProcessReadParams,
  ManagedProcessWaitParams,
  ManagedProcessWriteParams,
} from "./processes";

/** Request/response API surface (replaces HTTP routes). */
export interface Api {
  "host.ping": { params: void; result: { ok: true; ts: number } };
  "host.toolchain": {
    params: { cwd: string };
    result: {
      inventoryRevision: number;
      resolutionId: string;
      capabilities: Partial<Record<ToolCapabilityId, { provider: ToolProvider; version: string }>>;
    };
  };

  // Managed background processes (trusted Renderer control surface)
  "processes.list": {
    params: { includeExited?: boolean } | void;
    result: { revision: number; processes: ManagedProcessPublicInfo[] };
  };
  "processes.get": {
    params: { processId: string };
    result: ManagedProcessPublicInfo;
  };
  "processes.read": {
    params: ManagedProcessReadParams;
    result: ManagedProcessLogWindow;
  };
  "processes.wait": {
    params: ManagedProcessWaitParams;
    result: ManagedProcessLogWindow;
  };
  "processes.write": {
    params: ManagedProcessWriteParams;
    result: { ok: true; runId: string };
  };
  "processes.stop": {
    params: { processId: string; runId: string; mode?: "graceful" | "force" };
    result: ManagedProcessPublicInfo;
  };
  "processes.stopAll": {
    params: { mode?: "graceful" | "force" } | void;
    result: { ok: true; stopped: number };
  };
  "processes.restart": {
    params: { processId: string; runId: string };
    result: ManagedProcessPublicInfo;
  };
  "processes.dismiss": {
    params: { processId: string };
    result: { ok: true };
  };
  "processes.export": {
    params: { processId: string; runId: string; streams?: ManagedProcessLogStream[] };
    result: { saved: boolean; fileName?: string };
  };

  // Sessions & projects
  "sessions.list": {
    params: { cwd?: string } | void;
    result: { sessions: SessionInfo[]; runningSessionIds: string[] };
  };
  "sessions.get": {
    params: { id: string; includeState?: boolean; traceId?: string; historyWindow?: HistoryWindow };
    result: SessionDetail;
  };
  "sessions.context": {
    params: { id: string; leafId?: string; historyWindow?: HistoryWindow };
    result: { context: PagedContextInfo };
  };
  "sessions.contextPage": {
    params: { id: string; cursor: string; maxTurns?: number; maxBytes?: number };
    result: { context: PagedContextInfo };
  };
  "sessions.entryContent": {
    params: { id: string; entryId: string; blockIndex?: number };
    result: EntryContentResult;
  };
  "sessions.export": {
    params: { id: string; format?: "md" | "json" };
    result: { content: string; suggestedName: string };
  };
  "sessions.delete": { params: { id: string; force?: boolean }; result: { ok: true } };
  "sessions.rename": {
    params: { id: string; name: string };
    result: { ok: true };
  };

  "worktrees.list": {
    params: { projectRoot: string };
    result: {
      worktrees: WorktreeInfo[];
      projectRoot: string;
      isGit: boolean;
      isTopLevel: boolean;
    };
  };
  "worktrees.create": {
    params: { projectRoot: string; branch: string; cwd?: string };
    result: { worktree: WorktreeInfo };
  };
  "worktrees.remove": {
    params: { path: string; cwd?: string; force?: boolean };
    result: { ok: true };
  };

  "git.status": {
    params: { path: string };
    result: GitStatusResult;
  };

  // Agent lifecycle
  "agent.new": {
    params: {
      cwd: string;
      type?: string;
      message?: string;
      provider?: string;
      modelId?: string;
      toolNames?: string[];
      thinkingLevel?: string;
      [key: string]: unknown;
    };
    result: { sessionId: string; data?: unknown };
  };
  "agent.command": {
    params: { sessionId: string; command: AgentCommand };
    result: unknown;
  };
  "agent.state": {
    params: { sessionId: string };
    result: { running: boolean; state?: unknown };
  };
  /** Generate a concise session title from the first user message (silent LLM request, never touches session history). */
  "agent.generateTitle": {
    params: {
      sessionId: string;
      message: string;
      provider?: string;
      modelId?: string;
    };
    result: { title: string | null };
  };

  // Messaging channels
  "channels.list": { params: void; result: ChannelsSnapshot };
  "channels.accountUpsert": {
    params: { account: ChannelAccountConfig };
    result: ChannelsSnapshot;
  };
  "channels.accountConnect": {
    params: { account: ChannelAccountConfig };
    result: ChannelsSnapshot;
  };
  "channels.accountDelete": {
    params: { accountId: string };
    result: ChannelsSnapshot;
  };
  "channels.start": { params: { accountId: string }; result: { ok: true } };
  "channels.stop": { params: { accountId: string }; result: { ok: true } };
  "channels.restart": { params: { accountId: string }; result: { ok: true } };
  "channels.probe": { params: { accountId: string }; result: ChannelProbeResult };
  "channels.loginStart": {
    params: ChannelLoginStartRequest;
    result: ChannelLoginEvent;
  };
  "channels.loginWait": {
    params: { channel: ChannelId; sessionKey: string };
    result: ChannelLoginEvent;
  };
